const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const grindavik = ee.Geometry.Point(-22.4348, 63.8422); // Approximate center of Grindavík
  const reykjavik = ee.Geometry.Point(-21.9426, 64.1473); // Approximate center of Reykjavík

  const startDate = '2024-11-21';
  const endDate = '2024-11-22'; // End date is exclusive

  // 2. Data Acquisition & Check
  // Using daily Suomi-NPP VIIRS DNB VCMCFG_V2 for nighttime lights
  const viirsCollection = ee.ImageCollection('NOAA/VIIRS/DNB/VCMCFG_V2')
    .filterDate(startDate, endDate);

  const grindavikCollectionSize = await viirsCollection.filterBounds(grindavik).size().getInfo();
  const reykjavikCollectionSize = await viirsCollection.filterBounds(reykjavik).size().getInfo();

  if (grindavikCollectionSize === 0 || reykjavikCollectionSize === 0) {
    console.log(`Grindavík Images: ${grindavikCollectionSize}`);
    console.log(`Reykjavík Images: ${reykjavikCollectionSize}`);
    console.log("No data found for November 21, 2024, as it is a future date and GEE collections do not contain future data.");
    console.log("C1");
    return;
  }

  // If, by some unexpected chance, data was available (e.g., if the question were for a past date)
  // this part would continue the analysis. However, based on the C1 output above, this is unreachable
  // for the given question.
  try {
    const viirsImage = viirsCollection.first(); // Get the single image for the day
    if (!viirsImage) {
      console.log("No single image could be retrieved for the date.");
      console.log("C1");
      return;
    }

    // Define a cloud mask function
    const maskClouds = (image) => {
      const cloudMask = image.select('cloud_mask').eq(0); // 0 means clear, 1-3 means cloudy
      return image.updateMask(cloudMask);
    };

    // Apply cloud mask and select the average radiance band
    const processedImage = maskClouds(viirsImage).select('avg_rad');

    // Define a scale for reduction (VIIRS pixel size is ~750m, use a larger scale to avoid timeout)
    const scale = 1000;

    // 3. Processing & Pixel Count Check for Grindavík
    const grindavikPixelCount = await processedImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: grindavik.buffer(1000), // Buffer to get a small area
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    if (grindavikPixelCount === 0 || grindavikPixelCount === null) {
      console.log("No valid pixels for Grindavík after masking and processing.");
      console.log("C2");
      return;
    }

    // 3. Processing & Pixel Count Check for Reykjavík
    const reykjavikPixelCount = await processedImage.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: reykjavik.buffer(1000), // Buffer to get a small area
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    if (reykjavikPixelCount === 0 || reykjavikPixelCount === null) {
      console.log("No valid pixels for Reykjavík after masking and processing.");
      console.log("C2");
      return;
    }

    // 4. Calculation
    const grindavikMeanRad = await processedImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: grindavik.buffer(1000),
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    const reykjavikMeanRad = await processedImage.reduceRegion({
      reducer: ee.Reducer.mean(),
      geometry: reykjavik.buffer(1000),
      scale: scale,
      maxPixels: 1e9
    }).get('avg_rad').getInfo();

    // 5. Validation & Final Answer
    if (grindavikMeanRad === null || isNaN(grindavikMeanRad) ||
      reykjavikMeanRad === null || isNaN(reykjavikMeanRad)) {
      console.log("Calculation resulted in None/NaN for mean radiance.");
      console.log("C3");
      return;
    }

    console.log(`Grindavík (Pixels: ${grindavikPixelCount}): ${grindavikMeanRad.toFixed(4)} nW/cm²/sr`);
    console.log(`Reykjavík (Pixels: ${reykjavikPixelCount}): ${reykjavikMeanRad.toFixed(4)} nW/cm²/sr`);

    if (grindavikMeanRad > reykjavikMeanRad) {
      console.log("A");
    } else {
      console.log("B");
    }
  } catch (error) {
    console.error("An error occurred during processing:", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
